<script setup>
import { ref, watch, onMounted, onUnmounted } from 'vue'
import { useAppStore } from '../stores/app'
import api from '../api/client'
import { checkpointMatches } from '../utils/dispatchAlgorithms'
import TopologyGraph from '../components/TopologyGraph.vue'
import NodeResourcePanel from '../components/NodeResourcePanel.vue'
import TaskFlowTable from '../components/TaskFlowTable.vue'
const app=useAppStore(), source=ref('draft'), policy=ref('shortest_fastest'), checkpoint=ref(null), seed=ref(42), session=ref(null), snapshot=ref(null), selected=ref(null), route=ref(null), playing=ref(false), busy=ref(false), a=ref(0), b=ref(1), congestion=ref(.5); let timer
watch(source, () => { checkpoint.value = null; if (policy.value === 'heft_hetero') policy.value = 'shortest_fastest' })
async function create(){ pause(); const env=source.value==='draft' ? app.env : {preset_name:source.value,config:{}}; const data=await api.post('/sim/sessions',{...env,seed:seed.value,policy:policy.value,checkpoint_path:checkpoint.value}); session.value=data.session_id; snapshot.value=data.snapshot; selected.value=data.snapshot.nodes[0]; route.value=null }
async function step(action_id=null, slot=false){ if(!session.value || busy.value) return; busy.value=true; try { snapshot.value=await api.post(`/sim/sessions/${session.value}/${slot?'step-slot':'step'}`,slot ? {} : {action_id}); route.value=null; if(snapshot.value.done) pause() } finally { busy.value=false } }
async function perturb(data){ snapshot.value=await api.post(`/sim/sessions/${session.value}/perturb`,{source:a.value,target:b.value,...data}) }
function pause(){ playing.value=false; clearTimeout(timer) }
async function loop(){ if(!playing.value) return; await step(); if(playing.value) timer=setTimeout(loop,1000/(app.prefs.speed || 1)) }
function play(){ if(playing.value) pause(); else { playing.value=true; loop() } }
onMounted(()=>{ if(history.state?.checkpoint){ checkpoint.value=history.state.checkpoint; policy.value='checkpoint' } }); onUnmounted(pause)
</script>
<template><div class="page"><div class="page-head"><div><div class="eyebrow">SIMULATION SANDBOX</div><h1>仿真推演沙盘</h1><p>观察动态网络，逐任务干预调度决策。</p></div><div class="page-code">实时推演 / 02</div></div><section class="panel control-panel"><div class="control-row"><label>环境<el-select v-model="source" style="width:165px"><el-option label="工作台当前草稿" value="draft"/><el-option v-for="p in Object.keys(app.presets)" :key="p" :value="p"/></el-select></label><label>策略<el-select v-model="policy" style="width:170px"><el-option label="最短最快" value="shortest_fastest"/><el-option label="贪心估计" value="greedy_estimate"/><el-option label="随机" value="random"/><el-option v-if="(source === 'draft' ? app.env?.config : app.presets[source])?.enable_dag_mode" label="异构 HEFT" value="heft_hetero"/><el-option label="Checkpoint" value="checkpoint"/></el-select></label><label v-if="policy==='checkpoint'">权重<el-select v-model="checkpoint" filterable style="width:220px"><el-option v-for="c in app.checkpoints.filter(c => checkpointMatches(c, source === 'draft' ? app.env?.config : app.presets[source]))" :key="c.path" :label="c.run_dir+' / '+c.name" :value="c.path"/></el-select></label><label>种子<el-input-number v-model="seed" :controls="false" style="width:90px"/></label><el-button type="primary" @click="create">创建 / 重置会话</el-button></div><div class="control-row controls-bottom"><el-button :disabled="!session || busy || snapshot?.done" @click="step()">单步推演</el-button><el-button :disabled="!session || busy || snapshot?.done" @click="step(null,true)">推进一整时隙</el-button><el-button :disabled="!session || snapshot?.done" @click="play">{{ playing ? '暂停播放' : '自动播放' }}</el-button><label>速度<el-select v-model="app.prefs.speed" style="width:85px"><el-option v-for="s in [.5,1,2,4]" :key="s" :label="s+'×'" :value="s"/></el-select></label><span v-if="snapshot" class="session-meta">时隙 {{ snapshot.slot }} / {{ snapshot.episode_slots }} · 任务 {{ snapshot.task_index }} / {{ snapshot.total_tasks }}</span></div></section><div class="kpi-grid"><div v-for="k in [['任务完成率','task_success_rate'],['平均时延 (s)','avg_delay_s'],['平均能耗 (J)','avg_energy_j'],['负载方差','mean_load_variance']]" :key="k[1]" class="kpi"><span>{{ k[0] }}</span><strong>{{ snapshot?.metrics?.[k[1]] == null ? '—' : Number(snapshot.metrics[k[1]]).toFixed(3) }}</strong></div></div><div class="sandbox-grid"><section class="panel"><div class="panel-heading"><div><div class="eyebrow">NETWORK STATE</div><h3>云–边–端网络拓扑</h3></div><span class="chip">{{ snapshot?.links?.length || 0 }} 条链路</span></div><TopologyGraph :snapshot="snapshot" :selected="route" @select-node="selected=$event"/></section><section class="panel"><NodeResourcePanel :node="selected" :nodes="snapshot?.nodes || []" @select-node="selected=$event"/></section></div><section class="panel perturb"><div><div class="eyebrow">LINK CONTROL</div><h3>链路扰动注入</h3></div><label>边缘节点 <el-input-number v-model="a" :min="0" :max="(snapshot?.nodes.length || 2)-2" size="small"/></label><span>↔</span><el-input-number v-model="b" :min="0" :max="(snapshot?.nodes.length || 2)-2" size="small"/><el-button :disabled="!session" @click="perturb({active:false})">断开链路</el-button><el-button :disabled="!session" @click="perturb({active:true})">恢复链路</el-button><label class="slider-label">背景拥塞 {{ congestion.toFixed(2) }}<el-slider v-model="congestion" :min="0" :max="0.99" :step="0.01"/></label><el-button :disabled="!session" @click="perturb({congestion})">注入拥塞</el-button></section><section class="panel"><TaskFlowTable :snapshot="snapshot" manual @select-path="route=$event" @execute="step($event)"/></section></div></template>
